from fastapi import FastAPI, Request, Depends, HTTPException
from fastapi.responses import JSONResponse

app = FastAPI()

class SeatQuotaExceededError(Exception):
    def __init__(self):
        pass

@app.exception_handler(SeatQuotaExceededError)
async def seat_quota_handler(request: Request, exc: SeatQuotaExceededError):
    return JSONResponse(
        status_code=400,
        content={
            "error": "WorkspaceSeatsExhausted",
            "detail": "Workspace has reached maximum allowed member seats for its subscription plan"
        }
    )

@app.post("/workspaces/{workspace_id}/invitations")
async def invite_workspace_member(
    workspace_id: str,
    payload: InvitePayload,
    workspace_repo: WorkspaceRepo = Depends(get_workspace_repo),
    current_user: User = Depends(get_current_user)
):
    ws = await workspace_repo.find_by_id(workspace_id)
    if not ws:
        raise HTTPException(status_code=404, detail="Workspace does not exist")
    if not any(m.id == current_user.id and m.is_admin for m in ws.members):
        raise HTTPException(status_code=403, detail="Forbidden: only workspace administrators can manage invitations")

    if len(ws.members) >= ws.max_seats:
        raise SeatQuotaExceededError()

    return await workspace_repo.send_invite(workspace_id, payload.email, current_user.id)
